def solve(data):
    edges = data["edges"]
    n = data["n"]
    source = data["source"]
    target = data["target"]

    # Check if the graph has no edges
    if len(edges) == 0:
        return -1

    # Check if there is only one node
    if n == 1:
        return 0

    # Check if the source and target are the same node
    if source == target:
        return 1

    # Initialize the visited set and the edge count
    visited = set()
    edge_count = 0

    def dfs(node):
        nonlocal edge_count
        if node == target:
            return True
        if node in visited:
            return False
        visited.add(node)
        for neighbor in range(n):
            if neighbor != node and (neighbor, node) in edges:
                if dfs(neighbor):
                    edge_count += 1
                    return True
        return False

    # Perform DFS starting from the source
    if not dfs(source):
        return -1

    return edge_count

